#include <bits/stdc++.h>
using namespace std;

using lli = long long;

lli num[5] = {1, 2, 3, 4, 5};
lli arr[5], combinations[120][5], grid[6][6];
lli totalCombination = 0;
bool visited[5] = {};

void build(lli pos) {
    if (pos == 5) {
        for (lli i = 0; i < 5; ++i)
            combinations[totalCombination][i] = arr[i];
        ++totalCombination;
        return;
    }

    for (lli i = 0; i < 5; ++i) {
        if (!visited[i]) {
            visited[i] = true;
            arr[pos] = num[i];
            build(pos + 1);
            visited[i] = false;
        }
    }
}

lli getScore(const lli order[]) {
    lli score = 0;

    for (lli i = 0; i < 5; ++i) {
        for (lli j = i; j < 4; j += 2) {
            lli a = order[j], b = order[j + 1];
            score += grid[a][b] + grid[b][a];
        }
    }

    return score;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    build(0);

    while (cin >> grid[1][1]) {
        for (lli i = 1; i <= 5; ++i) {
            for (lli j = 1; j <= 5; ++j) {
                if (i == 1 && j == 1) continue;
                cin >> grid[i][j];
            }
        }

        lli maxScore = LLONG_MIN;
        for (lli i = 0; i < totalCombination; ++i)
            maxScore = max(maxScore, getScore(combinations[i]));

        cout << maxScore << '\n';
    }

    return 0;
}

