int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long grid[6][6];

    while (cin >> grid[1][1]) {
        for (int i = 1; i <= 5; ++i) {
            for (int j = 1; j <= 5; ++j) {
                if (i == 1 && j == 1) continue;
                cin >> grid[i][j];
            }
        }

        vector<int> p = {1, 2, 3, 4, 5};
        long long maxScore = LLONG_MIN;

        do {
            long long score = 0;
            for (int i = 0; i < 4; ++i) {
                score += grid[p[i]][p[i + 1]] + grid[p[i + 1]][p[i]];
            }
            for (int i = 2; i < 4; ++i) {
                score += grid[p[i]][p[i + 1]] + grid[p[i + 1]][p[i]];
            }
            maxScore = max(maxScore, score);
        } while (next_permutation(p.begin(), p.end()));

        cout << maxScore << '\n';
    }

    return 0;
}

